ins={(1,5),(2,3),(2,4),(2,5),(2,7),(3,3),(4,3),(4,4),(4,5),(4,6),(5,2),(5,6)}
out={(1,5),(2,1),(2,2),(3,2),(3,4),(3,5),(4,2),(4,4),(5,2),(5,3),(5,4),(6,1)}
# coordinate transform from 9x10 to 10x9 using rotations/reflections
transforms={
'cw':lambda r,c:(c,8-r), # gives 10x9
'ccw':lambda r,c:(9-c,r),
'flipud':lambda r,c:(8-r,c), # shape 9x10
'fliplr':lambda r,c:(r,9-c),
}
for name,f in transforms.items():
 q={f(r,c) for r,c in ins}
 print(name,len(q),q==out, sorted(q))
